 internal static class BrowserExtensionManagerTests {
  sealed class Fixture {
   internal readonly string root,data,bundle,legacy;
   internal readonly HashSet<string> registered=new HashSet<string>();
   internal readonly JavaScriptSerializer json=new JavaScriptSerializer();
   internal DateTime clock=new DateTime(2026,10,13,12,0,0,DateTimeKind.Utc);
   internal bool failMove;
   internal int catalogReads;
   internal Fixture(string parent,string name){root=Path.Combine(parent,name);data=Path.Combine(root,"data");bundle=Path.Combine(root,"bundle");legacy=Path.Combine(root,"old","browser-extension");Directory.CreateDirectory(bundle);SetVersion("1.0.0");}
   internal void SetVersion(string version){foreach(string file in BrowserExtensionManager.RuntimeFiles)File.WriteAllText(Path.Combine(bundle,file),file+" trusted "+version,new UTF8Encoding(false));WriteManifest(bundle,version,BrowserExtensionManager.PublicKey);File.WriteAllText(Path.Combine(bundle,"local-connection.js"),"MACHINE-SECRET-MUST-NOT-BE-COPIED");File.WriteAllText(Path.Combine(bundle,"unexpected.exe"),"DO NOT COPY");}
   internal void WriteManifest(string directory,string version,string key){Directory.CreateDirectory(directory);var value=new Dictionary<string,object>{{"manifest_version",3},{"name","Mori Desk · 图片与网址收藏"},{"version",version},{"background",new Dictionary<string,object>{{"service_worker","background.js"}}}};if(key!=null)value.Add("key",key);File.WriteAllText(Path.Combine(directory,"manifest.json"),json.Serialize(value),new UTF8Encoding(false));}
   internal BrowserExtensionStore Store(){return new BrowserExtensionStore(data,bundle,legacy,BrowserExtensionManager.PublicKey,id=>registered.Add(id),()=>registered.ToArray(),(source,target)=>{if(failMove&&source.Contains(".mori-stage-")){failMove=false;throw new IOException("synthetic rename failure");}Directory.Move(source,target);},()=>clock,()=>catalogReads++);}
   internal BrowserExtensionCatalog Catalog(){return json.Deserialize<BrowserExtensionCatalog>(File.ReadAllText(Path.Combine(data,"browser","extension-installs.json")));}
   internal Dictionary<string,object> Object(object value){return json.Deserialize<Dictionary<string,object>>(json.Serialize(value));}
   internal Dictionary<string,object> Request(BrowserExtensionInstall item,string op,string token=null,string client=null){var value=new Dictionary<string,object>{{"action","extensionControl"},{"op",op},{"_extensionId",item.extensionId},{"extensionId",item.extensionId},{"installationId",item.installationId},{"clientId",client??new string('a',32)},{"version",item.version},{"generation",item.generation}};if(token!=null)value.Add("token",token);return value;}
   internal Dictionary<string,object> Send(BrowserExtensionStore store,BrowserExtensionInstall item,string op,string token=null,string client=null){return Object(store.Handle(Request(item,op,token,client)));}
  }
  static bool Ok(Dictionary<string,object> result){object value;return result.TryGetValue("ok",out value)&&true.Equals(value);}
  static string Text(Dictionary<string,object> value,string field){object result;return value.TryGetValue(field,out result)?Convert.ToString(result):"";}
  static bool Rejects(Action action){try{action();return false;}catch(InvalidDataException){return true;}catch(IOException){return true;}catch(InvalidOperationException){return true;}}
  public static void Run(string root,Action<bool,string> check){
   string suite=Path.Combine(root,"extension-manager");Directory.CreateDirectory(suite);
   check(BrowserExtensionStore.KeyId(BrowserExtensionManager.PublicKey)=="ohmoflmbcmhahccacmlbggkpalcmmmae","extension fixed public key produces stable Chrome ID");
   check(BrowserExtensionStore.PathId(@"C:\MoriSynthetic\Legacy\browser-extension")=="ohoboebcmiggodaodjkpcneaafpkmkii","legacy path identity agrees with Chromium UTF-16 path hash");
   check(BrowserExtensionStore.PathId(@"c:\MoriSynthetic\Legacy\browser-extension")==BrowserExtensionStore.PathId(@"C:\MoriSynthetic\Legacy\browser-extension"),"keyless ID normalizes drive letter");
   FreshInstall(suite,check);RuntimeIo(suite,check);Updates(suite,check);SameVersionReload(suite,check);Rollback(suite,check);CrashRecovery(suite,check);DowngradeProtection(suite,check);Clients(suite,check);UpdateTimeouts(suite,check);StatusAggregation(suite,check);Legacy(suite,check);UnsafeCatalog(suite,check);
  }
  static void FreshInstall(string root,Action<bool,string> check){
   var f=new Fixture(root,"fresh");var store=f.Store();var initial=store.Status();check(!initial.connected&&!initial.pending&&initial.bundledVersion=="1.0.0"&&initial.version=="","uninstalled status exposes bundled version but no invented running version");
   var status=store.EnsureInstalled();var item=f.Catalog().installs.Single();check(Directory.Exists(item.path)&&item.path==Path.Combine(f.data,"browser","extension"),"new extension has stable managed folder");
   check(f.registered.SetEquals(new[]{item.extensionId})&&item.extensionId=="ohmoflmbcmhahccacmlbggkpalcmmmae","new install registers only its stable extension identity");
   string config=File.ReadAllText(Path.Combine(item.path,"local-connection.js"));check(config.Contains(item.installationId)&&!config.Contains("MACHINE-SECRET-MUST-NOT-BE-COPIED"),"pairing generated locally with persistent installation ID");check(!File.Exists(Path.Combine(item.path,"unexpected.exe")),"installer copies only explicit runtime allowlist");
   string safeStatus=f.json.Serialize(status);check(!safeStatus.Contains(item.lastToken)&&!safeStatus.Contains("endpoint")&&!safeStatus.Contains("MoriLocalConnection"),"status does not reveal updater token or pairing config");
   check(store.EnsureInstalled().path==item.path&&f.Catalog().installs.Single().installationId==item.installationId,"repeated setup preserves same installation identity");
   check(Ok(f.Send(store,item,"poll"))&&store.Status().connected&&store.Status().version=="1.0.0","authenticated heartbeat reports actually running version");
   var forged=f.Request(item,"poll");forged.Remove("_extensionId");check(!Ok(f.Object(store.Handle(forged))),"body extension ID cannot replace authenticated sender");forged=f.Request(item,"poll");forged["_extensionId"]=new string('b',32);check(!Ok(f.Object(store.Handle(forged))),"wrong authenticated extension ID rejected");forged=f.Request(item,"poll");forged["installationId"]=new string('b',32);check(!Ok(f.Object(store.Handle(forged))),"wrong installation identity rejected");
   check(Ok(f.Object(store.BridgeStatus(new Dictionary<string,object>{{"_extensionId",item.extensionId}}))),"bridge health works for registered identity without library access");check(Ok(f.Object(store.Handle(new Dictionary<string,object>{{"action","bridgeStatus"},{"_extensionId",item.extensionId}}))),"normal dispatch handles health without opening library");check(!Ok(f.Object(store.BridgeStatus(new Dictionary<string,object>{{"_extensionId",new string('p',32)}}))),"health rejects unpaired identity");
   File.WriteAllText(Path.Combine(item.path,"local-connection.js"),"old pairing");store.RefreshPairing();check(File.ReadAllText(Path.Combine(item.path,"local-connection.js")).Contains(item.installationId),"refresh pairing restores managed installation ID");
   f.registered.Add(new string('p',32));store.RegisterKnown();check(f.registered.Contains(new string('p',32)),"managed registration preserves unrelated allowed extension IDs");
  }
  static void Updates(string root,Action<bool,string> check){
   var f=new Fixture(root,"update");var store=f.Store();store.EnsureInstalled();var item=f.Catalog().installs.Single();string old=File.ReadAllText(Path.Combine(item.path,"background.js"));f.SetVersion("1.1.0");store.RequestUpdate();item=f.Catalog().installs.Single();string firstToken=item.pending.token;
   var response=f.Send(store,item,"poll");var update=response["update"] as Dictionary<string,object>;check(Ok(response)&&update!=null&&Text(update,"version")=="1.1.0","poll offers staged bundled version");store.RequestUpdate();check(f.Catalog().installs.Single().pending.token==firstToken,"repeated update request reuses intact pending stage");
   var request=f.Request(item,"apply",new string('0',64));request["path"]=Path.Combine(f.root,"arbitrary");check(!Ok(f.Object(store.Handle(request)))&&!Directory.Exists(Path.Combine(f.root,"arbitrary")),"wrong token cannot update arbitrary request path");
   File.AppendAllText(Path.Combine(item.pending.path,"background.js")," tamper");check(!Ok(f.Send(store,item,"apply",firstToken))&&File.ReadAllText(Path.Combine(item.path,"background.js"))==old,"tampered stage rejected before replacing installed code");
   store.RequestUpdate();item=f.Catalog().installs.Single();check(item.pending.token!=firstToken,"explicit retry repairs invalid staging without trusting tampered files");string token=item.pending.token;
   response=f.Send(store,item,"apply",token);item=f.Catalog().installs.Single();check(Ok(response)&&item.version=="1.1.0"&&item.pending==null,"authenticated apply atomically installs validated update");check(Directory.Exists(item.backup)&&File.ReadAllText(Path.Combine(item.backup,"background.js"))==old,"update retains original plugin backup");
   var stale=f.Request(item,"poll");stale["version"]="1.0.0";var staleResponse=f.Object(store.Handle(stale));check(staleResponse["update"]!=null&&store.Status().pending,"old running version reoffers reload after lost apply response");
   f.Send(store,item,"poll");check(!store.Status().pending,"new running version acknowledgment completes update status");
   check(Ok(f.Send(store,item,"apply",token)),"lost apply response can be retried idempotently by same profile");check(!Ok(f.Send(store,item,"apply",token,new string('b',32))),"consumed token cannot be replayed by another profile");
   check(File.ReadAllText(Path.Combine(item.path,"local-connection.js")).Contains(item.installationId)&&!File.Exists(Path.Combine(item.path,"unexpected.exe")),"update retains installation pairing without unrelated bundle files");
   var poll=f.Request(item,"poll");poll["version"]="1.0.0";store.Handle(poll);check(store.Status().version=="1.0.0"&&store.Status().installedVersion=="1.1.0","status distinguishes browser running code from installed files");
  }
  static void RuntimeIo(string root,Action<bool,string> check){
   var f=new Fixture(root,"runtime-io");var store=f.Store();store.EnsureInstalled();var item=f.Catalog().installs.Single();int reads=f.catalogReads;store.Status();check(f.catalogReads==reads+1,"status reads and validates catalog once per cross-process lock lease");reads=f.catalogReads;f.Object(store.BridgeStatus(new Dictionary<string,object>{{"_extensionId",item.extensionId}}));check(f.catalogReads==reads+1,"health status shares recovery snapshot instead of rereading catalog");
   string pairing=Path.Combine(item.path,"local-connection.js");var stamp=new DateTime(2002,3,4,5,6,7,DateTimeKind.Utc);File.SetLastWriteTimeUtc(pairing,stamp);store.RefreshPairing();check(File.GetLastWriteTimeUtc(pairing)==stamp&&File.ReadAllText(pairing).Contains(item.installationId),"refreshing managed pairing does not rewrite unchanged identity config");
   f.Send(store,item,"poll");string catalog=Path.Combine(f.data,"browser","extension-installs.json");File.SetLastWriteTimeUtc(catalog,stamp);int folders=Directory.GetDirectories(Path.Combine(f.data,"browser")).Length;store.RequestUpdate();check(f.Catalog().installs.Single().pending==null&&Directory.GetDirectories(Path.Combine(f.data,"browser")).Length==folders&&File.GetLastWriteTimeUtc(catalog)==stamp,"confirmed current intact plugin update is no-op without staging reload or durable write");
   var changed=f.Catalog();changed.installs.Single().activeVersion="9.0.0";File.WriteAllText(catalog,f.json.Serialize(changed));check(store.Status().availableVersion=="9.0.0","lease snapshot is discarded so following request sees external catalog changes");
   var corrupt=new Fixture(root,"io-corrupt");store=corrupt.Store();store.EnsureInstalled();item=corrupt.Catalog().installs.Single();corrupt.Send(store,item,"poll");File.AppendAllText(Path.Combine(item.path,"background.js")," corrupted");store.RequestUpdate();check(corrupt.Catalog().installs.Single().pending!=null,"same-version update still repairs changed runtime file");
   var missing=new Fixture(root,"io-missing");store=missing.Store();store.EnsureInstalled();item=missing.Catalog().installs.Single();missing.Send(store,item,"poll");File.Move(Path.Combine(item.path,"content.js"),Path.Combine(missing.root,"retained-content.js"));store.RequestUpdate();check(missing.Catalog().installs.Single().pending!=null,"same-version update still repairs missing runtime file");
   var old=new Fixture(root,"io-old");store=old.Store();store.EnsureInstalled();item=old.Catalog().installs.Single();var request=old.Request(item,"poll");request["version"]="0.9.0";store.Handle(request);store.RequestUpdate();check(old.Catalog().installs.Single().pending!=null,"current installed files still reload when browser reports old running code");
   var mixed=new Fixture(root,"io-mixed");store=mixed.Store();store.EnsureInstalled();item=mixed.Catalog().installs.Single();request=mixed.Request(item,"poll",null,new string('b',32));request["version"]="0.9.0";store.Handle(request);mixed.Send(store,item,"poll");store.RequestUpdate();check(mixed.Catalog().installs.Single().pending!=null,"confirmed new profile does not hide another recently running old profile");
   var pairBroken=new Fixture(root,"io-pairing");store=pairBroken.Store();store.EnsureInstalled();item=pairBroken.Catalog().installs.Single();pairBroken.Send(store,item,"poll");File.WriteAllText(Path.Combine(item.path,"local-connection.js"),"bad pairing");store.RequestUpdate();check(pairBroken.Catalog().installs.Single().pending!=null,"same-version no-op does not skip damaged generated pairing config");
  }
  static void SameVersionReload(string root,Action<bool,string> check){
   var f=new Fixture(root,"same-version-reload");var store=f.Store();store.EnsureInstalled();var oldWorker=f.Catalog().installs.Single();f.Send(store,oldWorker,"poll");
   File.AppendAllText(Path.Combine(oldWorker.path,"content.js")," damaged");store.RequestUpdate();var staged=f.Catalog().installs.Single();string token=staged.pending.token,generation=staged.pending.generation;
   check(!string.IsNullOrEmpty(generation)&&generation!=oldWorker.generation,"same-version repair stages a fresh generation while preserving extension identity");
   // The desktop commits, but its response is lost before the browser reloads.
   check(Ok(f.Send(store,oldWorker,"apply",token)),"same-version repair commits through the original worker");
   var response=f.Send(store,oldWorker,"poll");check(response["update"]!=null&&store.Status().pending&&!store.Status().upToDate,"old same-version poll after lost apply response cannot claim repair completed");
   var legacyPoll=f.Request(oldWorker,"poll");legacyPoll.Remove("generation");response=f.Object(store.Handle(legacyPoll));
   check(response["update"]!=null&&store.Status().pending,"pre-generation updater retains reload offer until it actually loads repaired scripts");
   check(Ok(f.Send(store,oldWorker,"apply",token)),"legacy worker may safely repeat only the idempotent update apply before reloading");
   var reloaded=f.Catalog().installs.Single();response=f.Send(store,reloaded,"poll");
   check(reloaded.generation==generation&&response["update"]==null&&!store.Status().pending&&store.Status().upToDate,"newly loaded exact generation confirms same-version repair without permanent pending state");
   store.RefreshPairing();check(new[]{"updater.js","preferences.js"}.All(file=>File.ReadAllText(Path.Combine(reloaded.path,file)).Contains("MoriInstalledGeneration = \""+generation+"\"")),"pairing refresh preserves the installed background and content script generations");
   store.RequestUpdate();check(f.Catalog().installs.Single().pending==null,"generated updater suffix remains an exact same-version no-op rather than causing update loops");
   var legacy=new Fixture(root,"pre-generation-catalog");store=legacy.Store();store.EnsureInstalled();var state=legacy.Catalog();state.installs.Single().generation="";state.installs.Single().awaitingReload=true;
   File.WriteAllText(Path.Combine(legacy.data,"browser","extension-installs.json"),legacy.json.Serialize(state));var request=legacy.Request(state.installs.Single(),"poll");request.Remove("generation");store.Handle(request);
   check(!store.Status().pending&&store.Status().upToDate,"existing catalogs without generation retain their legacy version acknowledgement compatibility");
  }
  static void Rollback(string root,Action<bool,string> check){
   var f=new Fixture(root,"rollback");var store=f.Store();store.EnsureInstalled();var item=f.Catalog().installs.Single();string old=File.ReadAllText(Path.Combine(item.path,"background.js"));f.SetVersion("2.0.0");store.RequestUpdate();item=f.Catalog().installs.Single();f.failMove=true;
   check(!Ok(f.Send(store,item,"apply",item.pending.token)),"rename failure is surfaced as failed update");check(Directory.Exists(item.path)&&File.ReadAllText(Path.Combine(item.path,"background.js"))==old&&f.Catalog().installs.Single().version=="1.0.0","rename failure restores original directory and catalog");
   check(Ok(f.Send(store,item,"apply",item.pending.token))&&f.Catalog().installs.Single().version=="2.0.0","same staged update can succeed after transient rename failure");
  }
  static void Clients(string root,Action<bool,string> check){
   var f=new Fixture(root,"clients");var store=f.Store();store.EnsureInstalled();var item=f.Catalog().installs.Single();f.SetVersion("1.2.0");store.RequestUpdate();item=f.Catalog().installs.Single();f.Send(store,item,"poll",null,new string('a',32));f.Send(store,item,"poll",null,new string('b',32));
   check(store.Status().profiles==2&&!Ok(f.Send(store,item,"apply",item.pending.token,new string('a',32))),"shared install cannot update while two browser profiles report active");
   f.clock=f.clock.AddSeconds(91);check(Ok(f.Send(store,item,"apply",item.pending.token,new string('a',32))),"closed second browser expires and remaining profile can update");
   f.SetVersion("1.3.0");store.RequestUpdate();item=f.Catalog().installs.Single();f.clock=f.clock.AddMinutes(31);check(!Ok(f.Send(store,item,"apply",item.pending.token)),"expired update token cannot modify installed extension");store.RequestUpdate();check(f.Catalog().installs.Single().pending.token!=item.pending.token,"explicit update refreshes expired one-use token");
  }
  static void UpdateTimeouts(string root,Action<bool,string> check){
   var f=new Fixture(root,"timeout-stage");var store=f.Store();store.EnsureInstalled();check(!store.Status().pending&&!store.Status().retryUpdate,"idle installed extension does not advertise update retry");f.SetVersion("1.1.0");store.RequestUpdate();var item=f.Catalog().installs.Single();string token=item.pending.token;f.clock=new DateTime(item.pending.expires,DateTimeKind.Utc);var status=store.Status();check(status.pending&&!status.retryUpdate,"staged update remains non-retryable through its token expiry boundary");
   f.clock=f.clock.AddTicks(1);status=store.Status();check(status.pending&&status.retryUpdate&&status.summary.Contains("超时")&&status.summary.Contains("重试"),"expired stage retains truthful pending status while offering explicit retry");check(f.Catalog().installs.Single().pending.token==token&&Directory.Exists(item.pending.path),"reading timeout status does not delete staged update or its token record");store.RequestUpdate();status=store.Status();check(status.pending&&!status.retryUpdate&&f.Catalog().installs.Single().pending.token!=token,"retrying expired stage creates fresh valid token and clears retry affordance");
   var ack=new Fixture(root,"timeout-ack");store=ack.Store();store.EnsureInstalled();ack.SetVersion("1.1.0");store.RequestUpdate();item=ack.Catalog().installs.Single();ack.Send(store,item,"apply",item.pending.token);item=ack.Catalog().installs.Single();ack.clock=new DateTime(item.lastApplied,DateTimeKind.Utc).AddMinutes(30);status=store.Status();check(status.pending&&!status.retryUpdate,"unacknowledged reload remains non-retryable through valid token window");
   ack.clock=ack.clock.AddTicks(1);status=store.Status();check(status.pending&&status.retryUpdate&&status.summary.Contains("超时")&&ack.Catalog().installs.Single().awaitingReload,"expired browser reload acknowledgment allows retry without pretending update completed");store.RequestUpdate();status=store.Status();check(status.pending&&!status.retryUpdate&&ack.Catalog().installs.Single().pending!=null,"fresh retry stage takes precedence over old expired reload acknowledgment");
  }
  static BrowserExtensionInstall AddLegacy(Fixture f,BrowserExtensionStore store,string version){f.WriteManifest(f.legacy,version,null);string id=BrowserExtensionStore.PathId(f.legacy);f.registered.Add(id);store.BootstrapLegacy(id);var item=f.Catalog().installs.Single(i=>i.legacy);f.Send(store,item,"poll");return item;}
  static void StatusAggregation(string root,Action<bool,string> check){
   var f=new Fixture(root,"stat-mixed");var store=f.Store();store.EnsureInstalled();var item=f.Catalog().installs.Single();f.Send(store,item,"poll");var old=f.Request(item,"poll",null,new string('b',32));old["version"]="0.9.0";store.Handle(old);f.clock=f.clock.AddTicks(1);f.Send(store,item,"poll");var status=store.Status();check(status.version=="1.0.0"&&status.profiles==2&&!status.upToDate&&!status.summary.Contains("已是最新"),"latest profile cannot conceal another recently running old version");f.clock=f.clock.AddSeconds(91);f.Send(store,item,"poll");check(store.Status().upToDate,"global current confirmation recovers after old profile expires and latest browser acknowledges");
   f=new Fixture(root,"stat-pending");store=f.Store();store.EnsureInstalled();var fixedItem=f.Catalog().installs.Single();f.Send(store,fixedItem,"poll");var legacyItem=AddLegacy(f,store,"1.0.0");check(store.Status().upToDate,"matching acknowledged fixed and legacy installations can be globally current");f.SetVersion("2.0.0");store.RequestUpdate();legacyItem=f.Catalog().installs.Single(i=>i.legacy);f.Send(store,legacyItem,"apply",legacyItem.pending.token);legacyItem=f.Catalog().installs.Single(i=>i.legacy);f.clock=f.clock.AddTicks(1);f.Send(store,legacyItem,"poll");status=store.Status();check(status.path==legacyItem.path&&status.version=="2.0.0"&&status.pending&&!status.upToDate&&!status.retryUpdate,"selected current legacy installation cannot hide fixed installation pending update");
   var state=f.Catalog();state.installs.Single(i=>!i.legacy).pending.expires=f.clock.Ticks-1;File.WriteAllText(Path.Combine(f.data,"browser","extension-installs.json"),f.json.Serialize(state));check(store.Status().retryUpdate,"global retry is enabled when the only remaining pending installation has expired");f.SetVersion("2.1.0");store.RequestUpdate();state=f.Catalog();state.installs.Single(i=>!i.legacy).pending.expires=f.clock.Ticks-1;File.WriteAllText(Path.Combine(f.data,"browser","extension-installs.json"),f.json.Serialize(state));check(store.Status().pending&&!store.Status().retryUpdate,"one fresh installation stage prevents retry while another expired stage remains pending");foreach(var installation in state.installs)installation.pending.expires=f.clock.Ticks-1;File.WriteAllText(Path.Combine(f.data,"browser","extension-installs.json"),f.json.Serialize(state));check(store.Status().retryUpdate,"all expired installation stages permit explicit global retry");
   f=new Fixture(root,"stat-newer");f.SetVersion("3.0.0");store=f.Store();store.EnsureInstalled();fixedItem=f.Catalog().installs.Single();f.Send(store,fixedItem,"poll");f.Send(store,fixedItem,"poll",null,new string('b',32));f.SetVersion("2.0.0");legacyItem=AddLegacy(f,store,"2.0.0");status=store.Status();check(status.path==legacyItem.path&&status.version=="2.0.0"&&status.availableVersion=="3.0.0"&&status.profiles==2&&!status.upToDate&&status.summary.Contains("不会降级"),"selected legacy status retains other installation newer version and maximum active profile count");
   f=new Fixture(root,"stat-unacked");store=f.Store();store.EnsureInstalled();AddLegacy(f,store,"1.0.0");check(store.Status().connected&&!store.Status().pending&&!store.Status().upToDate,"connected legacy installation does not confirm a fixed installation that never reported its running version");
  }
  static BrowserExtensionCatalog Journal(Fixture f){var state=f.Catalog();var item=state.installs.Single();state.recovery=new BrowserExtensionRecovery{installationId=item.installationId,token=item.pending.token,stage=item.pending.path,backup=item.path+".mori-backup-"+Guid.NewGuid().ToString("N"),client=new string('a',32),started=f.clock.Ticks,hadOriginal=Directory.Exists(item.path)};File.WriteAllText(Path.Combine(f.data,"browser","extension-installs.json"),f.json.Serialize(state));return state;}
  static void CrashRecovery(string root,Action<bool,string> check){
   var before=new Fixture(root,"crash-before-move");var store=before.Store();store.EnsureInstalled();before.SetVersion("2.0.0");store.RequestUpdate();var state=Journal(before);var item=state.installs.Single();string original=File.ReadAllText(Path.Combine(item.path,"background.js"));store.Status();
   check(before.Catalog().recovery==null&&before.Catalog().installs.Single().pending!=null&&File.ReadAllText(Path.Combine(item.path,"background.js"))==original&&Directory.Exists(state.recovery.stage),"crash before rename clears journal and preserves original plus staged update");
   var oldMoved=new Fixture(root,"crash-old-moved");store=oldMoved.Store();store.EnsureInstalled();oldMoved.SetVersion("2.0.0");store.RequestUpdate();state=Journal(oldMoved);item=state.installs.Single();original=File.ReadAllText(Path.Combine(item.path,"background.js"));Directory.Move(item.path,state.recovery.backup);store.Status();
   check(oldMoved.Catalog().recovery==null&&oldMoved.Catalog().installs.Single().version=="1.0.0"&&File.ReadAllText(Path.Combine(item.path,"background.js"))==original&&Directory.Exists(state.recovery.stage),"crash between directory renames restores original and retains validated stage");
   var newMoved=new Fixture(root,"crash-new-moved");store=newMoved.Store();store.EnsureInstalled();newMoved.SetVersion("2.0.0");store.RequestUpdate();state=Journal(newMoved);item=state.installs.Single();original=File.ReadAllText(Path.Combine(item.path,"background.js"));Directory.Move(item.path,state.recovery.backup);Directory.Move(state.recovery.stage,item.path);store.Status();var recovered=newMoved.Catalog().installs.Single();
   check(newMoved.Catalog().recovery==null&&recovered.version=="2.0.0"&&recovered.pending==null&&recovered.awaitingReload&&Directory.Exists(recovered.backup)&&File.ReadAllText(Path.Combine(recovered.backup,"background.js"))==original,"crash after new rename verifies all files and finalizes metadata without deleting backup");
