   var pending=new Fixture(root,"downgrade-pending");store=pending.Store();store.EnsureInstalled();pending.SetVersion("1.1.0");store.RequestUpdate();item=pending.Catalog().installs.Single();original=File.ReadAllText(Path.Combine(item.path,"background.js"));newer=pending.Request(item,"poll");newer["version"]="1.2.0";store.Handle(newer);var apply=pending.Request(item,"apply",item.pending.token);apply["version"]="1.2.0";
   check(!Ok(pending.Object(store.Handle(apply)))&&File.ReadAllText(Path.Combine(item.path,"background.js"))==original&&pending.Catalog().recovery==null,"apply rechecks runtime version and refuses previously staged downgrade before any rename");
